<dialog id="enroll-dialog" <?= isset($_GET['enroll']) || (!empty($_SESSION['old']) && isset($_SESSION['old']['student_id']))?'data-auto-open':'' ?>><div class="dialog-heading"><h2>Enroll student</h2><button class="icon-button" data-close aria-label="Close">×</button></div><form method="post" action="<?= e(url('learning/enrollment')) ?>" data-enrollment-form><?= csrf_field() ?><input type="hidden" name="batch_id" value="<?= $batch['id'] ?>"><div class="form-grid"><?php $options=[''=>'Choose a student']; foreach($available as $s) $options[$s['id']]=$s['name'].' · '.$s['phone']; choose('Student','student_id',$options,(int)($_GET['student']??0)); input('Enrollment date','enrolled_on','date',date('Y-m-d')); input('Total course fee','amount','number',$batch['fee']); input('Deposit / initial payment','deposit','number',$batch['fee']); input('Payment due date','due_date','date',date('Y-m-d')); choose('Payment method','method',['Cash'=>'Cash','Bank transfer'=>'Bank transfer','Mobile payment'=>'Mobile payment']); ?></div><label class="foc-option"><input type="checkbox" name="is_foc" value="1" <?= old('is_foc')==='1'?'checked':'' ?>><span>FOC (free of charge)<small>No payment is recorded and nothing is added to finance income.</small></span></label><div class="info-note">Enter the total fee and the deposit received on the enrollment date (zero is allowed). Pay the remaining balance in installments from Payments. Only money received is added to finance income. Select FOC for a free enrollment.</div><div class="form-footer"><button type="button" class="button" data-close>Cancel</button><button class="button primary" <?= !$available?'disabled':'' ?>>Enroll student</button></div></form></dialog>
